;; --------------------------------------------------------------------
;; SEND_BYTE_TO_PRINTER -- &4137 to &414E
;;
;; Takes:     A, BC
;; Leaves:    A, F
;; Preserves: BC (saved and restored)
;; Ends:      RET
;;
;; ? drives OUT (C),A, OUT (C),B.
;;
;; Shown for this routine in disasm/:
;;
;;     Send the byte in A to whichever printer LPRINT MODE selected.
;;     
;;     SORP again: zero takes the parallel path, which reads the port pair
;;     out of the ROM's LPTPRT1, writes the data one port below it and then
;;     strobes with B and B-1; non-zero takes the serial path, which reads
;;     SPORT and writes to register 3 of the SCC2691.
;;     
;;     It sat in the middle of the variable block as data until now, because
;;     nothing reaches it at &4137.  The one call is &5A55, which does
;;     CALL &8137 -- this page through the window -- and while that was
;;     being credited to the DOS page it read as a call to DOS_FSTR1, a
;;     one-byte variable holding a file number.  Following the window
;;     instead makes it thirty-four bytes of obvious code, and gives the
;;     printer loop above the routine it was plainly missing.
;; --------------------------------------------------------------------

SEND_BYTE_TO_PRINTER:
               PUSH BC                         ; 4137 C5
               LD C,A                          ; 4138 4F
               LD A,(SORP+&4000)               ; 4139 3A 06 80
               AND A                           ; 413C A7
               LD A,C                          ; 413D 79
               JR NZ,SEND_BYTE_TO_PRINTER_1    ; 413E 20 0F
               LD BC,(LPTPRT1)                 ; 4140 ED 4B 10 5A
               DEC C                           ; 4144 0D
               OUT (C),A                       ; 4145 ED 79
               INC C                           ; 4147 0C
               OUT (C),B                       ; 4148 ED 41
               DEC B                           ; 414A 05
               OUT (C),B                       ; 414B ED 41
               POP BC                          ; 414D C1
               RET                             ; 414E C9

;; --------------------------------------------------------------------
;; SEND_BYTE_TO_PRINTER_1 -- &414F to &4158
;;
;; Takes:     A
;; Leaves:    BC
;; Ends:      RET
;;
;; ? drives OUT (C),A.
;; --------------------------------------------------------------------

; ---- SEND_BYTE_TO_PRINTER_1 ---- from &413E when A <> 0
SEND_BYTE_TO_PRINTER_1:
               LD BC,(SPORT+&4000)             ; 414F ED 4B 0B 80
               LD B,&03                        ; 4153 06 03
               OUT (C),A                       ; 4155 ED 79
               POP BC                          ; 4157 C1
               RET                             ; 4158 C9

;; --------------------------------------------------------------------
;; FN_SVAL_S -- &4159 to &415F
;;
;; Takes:     A, B, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls EXPECT_NEXT_LPAREN_AND_NUMBER, CALL_EXPNUM; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     SVAL$ -- token FF 2E.
;;     
;;         SVAL$(number,characters)
;;     
;;     Packs a number into a 2, 3, 4 or 5-character string so it can sit in a
;;     fixed-width field.  2 characters take whole numbers 0-65535; 3, 4 and 5
;;     take the full range with about 5, 7 and 9 correct digits.  NVAL is the
;;     inverse.
;;     
;;     An array of these sorts about four times faster than the equivalent
;;     numeric array, which is the manual's reason for SORT not supporting
;;     numeric arrays at all.
;;     
;;     Manual: "SVAL$ - converting numbers to strings".
;; --------------------------------------------------------------------

FN_SVAL_S:
               CALL EXPECT_NEXT_LPAREN_AND_NUMBER ; 4159 CD 4A 44
               CALL CALL_EXPNUM                ; 415C CD 85 44
               PUSH AF                         ; 415F F5

;; --------------------------------------------------------------------
;; FN_SVAL_S_1 -- &4160 to &4178
;;
;; Takes:     B, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;; Ends:      JR
;;
;; ? drives IN A,(LMPR); calls EXPECT_RPAREN, CALL_GETINT, CMR.
;; --------------------------------------------------------------------

; ---- FN_SVAL_S_1 ---- from DOS &773A
FN_SVAL_S_1:
               CALL EXPECT_RPAREN              ; 4160 CD 54 44
               POP AF                          ; 4163 F1
               RET NC                          ; 4164 D0
               CALL CALL_GETINT                ; 4165 CD 76 44
               SUB &02                         ; 4168 D6 02
               JR NZ,FN_SVAL_S_FAIL            ; 416A 20 0D
               CALL CALL_GETINT                ; 416C CD 76 44
               LD H,C                          ; 416F 61
               LD L,B                          ; 4170 68
               LD (V41C0),HL                   ; 4171 22 C0 41
               LD BC,&0002                     ; 4174 01 02 00
               JR FN_SVAL_S_3                  ; 4177 18 3B

;; --------------------------------------------------------------------
;; FN_SVAL_S_FAIL -- &4179 to &41AC
;;
;; Takes:     A, BC, DE
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? reaches the ROM through DKP2; calls CMR, WRTBC; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- FN_SVAL_S_FAIL ---- from &416A when A <> &02
FN_SVAL_S_FAIL:
               CP &04                          ; 4179 FE 04
               JP NC,REP_ARGUMENT              ; 417B D2 BC 43
               PUSH BC                         ; 417E C5
               LD HL,FN_SVAL_S_4               ; 417F 21 00 4F
               LD C,&EF                        ; 4182 0E EF
               CALL WRTBC                      ; 4184 CD B3 45
               LD BC,&3431                     ; 4187 01 31 34
               CALL WRTBC                      ; 418A CD B3 45
               ; call the ROM at DKP2 with ROM1 paged in, and page back on the way out
               CALL CMR                        ; 418D CD F0 44
               DEFW DKP2                      ; 4190 00 4F
               CALL CALL_GETSTR                ; 4192 CD 6D 44
               LD HL,V41C4                     ; 4195 21 C4 41
               LD (HL),B                       ; 4198 70
               DEC HL                          ; 4199 2B
               LD (HL),C                       ; 419A 71
               DEC HL                          ; 419B 2B
               LD (HL),D                       ; 419C 72
               DEC HL                          ; 419D 2B
               RL E                            ; 419E CB 13
               RRA                             ; 41A0 1F
               RR E                            ; 41A1 CB 1B
               LD (HL),E                       ; 41A3 73
               DEC HL                          ; 41A4 2B
               LD (HL),A                       ; 41A5 77
               RLA                             ; 41A6 17
               JR C,FN_SVAL_S_2                ; 41A7 38 0A
               SET 7,(HL)                      ; 41A9 CB FE
               LD B,&05                        ; 41AB 06 05

;; --------------------------------------------------------------------
;; FN_SVAL_S_LOOP -- &41AD to &41B2
;;
;; Takes:     B, HL
;; Leaves:    A, F, B, HL
;; --------------------------------------------------------------------

; ---- FN_SVAL_S_LOOP ---- from &41B1 when B is not 0 yet
FN_SVAL_S_LOOP:
               LD A,(HL)                       ; 41AD 7E
               CPL                             ; 41AE 2F
               LD (HL),A                       ; 41AF 77
               INC HL                          ; 41B0 23
               DJNZ FN_SVAL_S_LOOP             ; 41B1 10 FA

;; --------------------------------------------------------------------
;; FN_SVAL_S_2 -- &41B3 to &41B3
;;
;; Takes:     nothing in registers
;; Leaves:    BC
;; --------------------------------------------------------------------

; ---- FN_SVAL_S_2 ---- from &41A7 when bit 7 was set
FN_SVAL_S_2:
               POP BC                          ; 41B3 C1

;; --------------------------------------------------------------------
;; FN_SVAL_S_3 -- &41B4 to &41B9
;;
;; Takes:     nothing in registers
;; Leaves:    A, F, DE
;;
;; ? drives IN A,(LMPR); falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- FN_SVAL_S_3 ---- from &4177
FN_SVAL_S_3:
               IN A,(LMPR)                     ; 41B4 DB FA
               INC A                           ; 41B6 3C
               LD DE,V41C0+&4000               ; 41B7 11 C0 81

;; --------------------------------------------------------------------
;; CALL_STKSTR -- &41BA to &41C4
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? reaches the ROM through STKSTR; calls CMR; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- CALL_STKSTR ---- from &47C9, &4E30, &56C7
CALL_STKSTR:
               ; call the ROM at STKSTR with ROM1 paged in, and page back on the way out
               CALL CMR                        ; 41BA CD F0 44
               DEFW STKSTR                    ; 41BD 27 01
               RET                             ; 41BF C9

; ---- V41C0 ---- from &4171
V41C0:
               DEFB &00,&00,&00,&00                                             ; 41C0 ....  zero fill

; ---- V41C4 ---- from &4195
V41C4:
               DEFB &00                                                         ; 41C4 .

;; --------------------------------------------------------------------
;; CALL_STKSTR_LOOP -- &41C5 to &41E3
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? reaches the ROM through J_SBUFFET; calls CMR; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

