;; --------------------------------------------------------------------
;; REPORT -- &43BE to &43C2
;;
;; Takes:     BC, DE, HL, IY
;; Leaves:    F, BC, DE, HL
;;
;; ? reaches the ROM through DOS_REPORTA-&4000; calls CALLDOS; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     Report the BASIC error whose number is in A.
;;     
;;     The entry points above it are a chain: each loads its own number into A
;;     and then falls through, with LD HL,nn swallowing the next two bytes so
;;     that the following LD A,n is never executed.  &21 on its own in the
;;     listing is one of those skips.
;;     
;;     It calls &51A0 in the DOS page, which stashes A and goes to DERR.
;; --------------------------------------------------------------------

; ---- REPORT ---- from &4BA5, &4F8D when A >= &04, &5B1F, &5B7E, &5F28, &657B, &6DF9
REPORT:
               ; call DOS_REPORTA-&4000 in the other page: LMPR is switched first, so that address is how the other listing numbers it
               CALL CALLDOS                    ; 43BE CD C1 42
               DEFW DOS_REPORTA-&4000         ; 43C1 A0 51

;; --------------------------------------------------------------------
;; POINT_INTO_VARIABLE -- &43C3 to &43D4
;;
;; Takes:     DE, HL
;; Leaves:    A, F, BC, HL
;;
;; ? reaches the ROM through STRLOCN; drives IN A,(HMPR); calls NRRDD; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     The variable the ROM's LOOKVARS last found, paged in and pointed
;;     eleven bytes into.  STRLOCN is the ROM's own "(2) USED BY LOOKVARS",
;;     so it holds where that search stopped; this reads it through NRRDD,
;;     takes the type byte into C, and adds &0B.
;; --------------------------------------------------------------------

; ---- POINT_INTO_VARIABLE ---- from &7103
POINT_INTO_VARIABLE:
               IN A,(HMPR)                     ; 43C3 DB FB
               PUSH AF                         ; 43C5 F5
               ; read the ROM variable STRLOCN -- the word below is its address, and the call returns past it
               CALL NRRDD                      ; 43C6 CD 5F 45
               DEFW STRLOCN                   ; 43C9 BC 5B
               LD H,B                          ; 43CB 60
               LD L,C                          ; 43CC 69
               LD C,(HL)                       ; 43CD 4E
               EX DE,HL                        ; 43CE EB
               LD HL,&000B                     ; 43CF 21 0B 00
               ADD HL,DE                       ; 43D2 19
               JR POINT_INTO_VARIABLE_1        ; 43D3 18 0D

;; --------------------------------------------------------------------
;; FIND_VARIABLE -- &43D5 to &43E1
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? drives IN A,(HMPR); calls TEST_RUNNING, CALL_LOOKVARS; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     Look a variable up and complain if it is not there.
;;     
;;     Returns immediately while the line is only being syntax-checked.
;;     Otherwise it saves HMPR, calls the ROM's LOOKVARS through the thunk
;;     above, and reports "Not found" if that comes back with Z.  What
;;     follows reads FLAGS bit 6 -- the ROM's numeric-or-string flag -- and
;;     the type bits in C, and refuses the combination that does not make
;;     sense with "Argument".
;; --------------------------------------------------------------------

; ---- FIND_VARIABLE ---- from &4759, &484C, &4B45, &700F, &7055
FIND_VARIABLE:
               CALL TEST_RUNNING               ; 43D5 CD E2 44
               JR Z,FIND_VARIABLE_DONE         ; 43D8 28 48
               IN A,(HMPR)                     ; 43DA DB FB
               PUSH AF                         ; 43DC F5
               CALL CALL_LOOKVARS              ; 43DD CD E7 45
               JR Z,REP_NOT_FOUND              ; 43E0 28 D1

;; --------------------------------------------------------------------
;; POINT_INTO_VARIABLE_1 -- &43E2 to &43EF
;;
;; Takes:     DE, HL
;; Leaves:    A, F, HL
;;
;; ? reaches the ROM through FLAGS; calls NRRD; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- POINT_INTO_VARIABLE_1 ---- from &43D3
POINT_INTO_VARIABLE_1:
               ; read the ROM variable FLAGS -- the word below is its address, and the call returns past it
               CALL NRRD                       ; 43E2 CD 6A 45
               DEFW FLAGS                     ; 43E5 3B 5C
               BIT 6,A                         ; 43E7 CB 77
               PUSH AF                         ; 43E9 F5
               JR Z,FIND_VARIABLE_1            ; 43EA 28 04
               BIT 5,C                         ; 43EC CB 69
               JR NZ,REP_ARGUMENT              ; 43EE 20 CC

;; --------------------------------------------------------------------
;; FIND_VARIABLE_1 -- &43F0 to &440C
;;
;; Takes:     C, HL
;; Leaves:    A, F, BC, DE, HL
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- FIND_VARIABLE_1 ---- from &43EA when bit 6 of A clear
FIND_VARIABLE_1:
               LD A,C                          ; 43F0 79
               AND &60                         ; 43F1 E6 60
               JR Z,FIND_VARIABLE_2            ; 43F3 28 18
               INC HL                          ; 43F5 23
               INC HL                          ; 43F6 23
               INC HL                          ; 43F7 23
               LD A,(HL)                       ; 43F8 7E
               INC HL                          ; 43F9 23
               LD C,(HL)                       ; 43FA 4E
               INC HL                          ; 43FB 23
               LD B,(HL)                       ; 43FC 46
               INC HL                          ; 43FD 23
               DEC A                           ; 43FE 3D
               JR Z,FIND_VARIABLE_3            ; 43FF 28 19
               DEC A                           ; 4401 3D
               JR NZ,REP_ARGUMENT              ; 4402 20 B8
               POP AF                          ; 4404 F1
               POP DE                          ; 4405 D1
               LD A,D                          ; 4406 7A
               LD E,(HL)                       ; 4407 5E
               INC HL                          ; 4408 23
               LD D,(HL)                       ; 4409 56
               INC HL                          ; 440A 23
               SCF                             ; 440B 37
               RET                             ; 440C C9

;; --------------------------------------------------------------------
;; FIND_VARIABLE_2 -- &440D to &4419
;;
;; Takes:     HL
;; Leaves:    A, F, BC, HL
;; --------------------------------------------------------------------

; ---- FIND_VARIABLE_2 ---- from &43F3 when no bit of &60 is set
FIND_VARIABLE_2:
               LD A,(HL)                       ; 440D 7E
               INC HL                          ; 440E 23
               LD C,(HL)                       ; 440F 4E
               INC HL                          ; 4410 23
               LD B,(HL)                       ; 4411 46
               INC HL                          ; 4412 23
               RRCA                            ; 4413 0F
               RRCA                            ; 4414 0F
               XOR B                           ; 4415 A8
               AND &C0                         ; 4416 E6 C0
               XOR B                           ; 4418 A8
               LD B,A                          ; 4419 47

;; --------------------------------------------------------------------
;; FIND_VARIABLE_3 -- &441A to &4421
;;
;; Takes:     nothing in registers
;; Leaves:    A, F, DE
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- FIND_VARIABLE_3 ---- from &43FF when A reaches 0
FIND_VARIABLE_3:
               POP AF                          ; 441A F1
               POP DE                          ; 441B D1
               LD A,D                          ; 441C 7A
               LD DE,&0001                     ; 441D 11 01 00
               SCF                             ; 4420 37
               RET                             ; 4421 C9

;; --------------------------------------------------------------------
;; FIND_VARIABLE_DONE -- &4422 to &4426
;;
;; Takes:     A, BC, DE, HL
