;; --------------------------------------------------------------------
;; LONGADDR_TO_PAGED -- &4427 to &4432
;;
;; Takes:     A, H
;; Leaves:    A, F, H
;; Ends:      RET
;;
;; Shown for this routine in disasm/:
;;
;;     Turn a long address into a page number and a windowed address.
;;     
;;     Takes a 64K bank in A and a 16-bit offset in HL, and returns the 16K
;;     page holding that byte in A with HL moved into &8000-&BFFF, ready
;;     for HMPR.  The top two bits of HL choose which of the bank's four
;;     pages, which is what the two RL H / RLA pairs move into A; the SCF
;;     before the last RR H is what forces bit 7 of H and puts the address
;;     in the window.
;;     
;;     Bank 5 offset &2000 comes out as page 20 at &A000.  PAGED_TO_LONG
;;     is the exact inverse.
;;     
;;     Worked out by running the shifts rather than by reading them: the
;;     sequence is short but the carry is doing three different jobs.
;; --------------------------------------------------------------------

; ---- LONGADDR_TO_PAGED ---- from &479A, &51D1, &6FCF, &6FEE, &6FFC, &70A7
LONGADDR_TO_PAGED:
               RL H                            ; 4427 CB 14
               RLA                             ; 4429 17
               RL H                            ; 442A CB 14
               RLA                             ; 442C 17
               RR H                            ; 442D CB 1C
               SCF                             ; 442F 37
               RR H                            ; 4430 CB 1C
               RET                             ; 4432 C9

;; --------------------------------------------------------------------
;; MULTIPLY_HL_BY_DE -- &4433 to &443B
;;
;; Takes:     A, HL
;; Leaves:    A, F, BC, HL, IY
;;
;; Shown for this routine in disasm/:
;;
;;     Multiply HL by DE into the 24-bit result A:HL, carry set if it will
;;     not fit.
;;     
;;     Shift and add, sixteen times round.  The multiplier is moved into IY
;;     so that HL is free to be the low half of the accumulator, and A the
;;     top eight bits; C is zeroed at the start and never touched again, so
;;     the ADC A,C in the loop is really just adding the carry.  Either the
;;     shift or the add overflowing returns immediately with carry set, and
;;     the AND A at the end is what clears it on the way out of a good one.
;; --------------------------------------------------------------------

; ---- MULTIPLY_HL_BY_DE ---- from &4791, &6FE6, &6FEB, &711E
MULTIPLY_HL_BY_DE:
               LD B,&10                        ; 4433 06 10
               PUSH HL                         ; 4435 E5
               POP IY                          ; 4436 FD E1
               XOR A                           ; 4438 AF
               LD H,A                          ; 4439 67
               LD L,A                          ; 443A 6F
               LD C,A                          ; 443B 4F

;; --------------------------------------------------------------------
;; MULTIPLY_HL_BY_DE_LOOP -- &443C to &4445
;;
;; Takes:     A, C, DE, HL, IY
;; Leaves:    A, F, HL, IY
;; --------------------------------------------------------------------

; ---- MULTIPLY_HL_BY_DE_LOOP ---- from &4446 when B is not 0 yet
MULTIPLY_HL_BY_DE_LOOP:
               ADD HL,HL                       ; 443C 29
               ADC A,A                         ; 443D 8F
               RET C                           ; 443E D8
               ADD IY,IY                       ; 443F FD 29
               JR NC,MULTIPLY_HL_BY_DE_DONE    ; 4441 30 03
               ADD HL,DE                       ; 4443 19
               ADC A,C                         ; 4444 89
               RET C                           ; 4445 D8

;; --------------------------------------------------------------------
;; MULTIPLY_HL_BY_DE_DONE -- &4446 to &4449
;;
;; Takes:     A, B
;; Leaves:    A, F, B
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- MULTIPLY_HL_BY_DE_DONE ---- from &4441
MULTIPLY_HL_BY_DE_DONE:
               DJNZ MULTIPLY_HL_BY_DE_LOOP     ; 4446 10 F4
               AND A                           ; 4448 A7
               RET                             ; 4449 C9

