;;     command may be followed by another on the same line.
;; --------------------------------------------------------------------

; ---- AT_END_OF_STATEMENT ---- from &44D0, &4918, &6126, &6809
AT_END_OF_STATEMENT:
               CALL CALL_GETCHAR               ; 44BC CD 67 44
               CP CH_CR                        ; 44BF FE 0D
               RET Z                           ; 44C1 C8
               CP CH_COLON                     ; 44C2 FE 3A
               RET                             ; 44C4 C9

