               OR SYSPAGE_IN_B                 ; 4517 F6 1F
               LD HL,(V4076+&4000)             ; 4519 2A 76 80
               DI                              ; 451C F3
               OUT (LMPR),A                    ; 451D D3 FA
               ; the stack is being reset, so this path does not return
               LD SP,HL                        ; 451F F9
               EI                              ; 4520 FB
               LD HL,(DOSSTK)                  ; 4521 2A 59 5C
               LD (DOSSTK),IY                  ; 4524 FD 22 59 5C
               PUSH IY                         ; 4528 FD E5
               PUSH BC                         ; 452A C5
               PUSH HL                         ; 452B E5
               LD HL,SYS_GAP_BLOCK+&0E         ; 452C 21 A4 58
               PUSH HL                         ; 452F E5
               PUSH DE                         ; 4530 D5

L4531:
               LD A,&00                        ; 4531 3E 00  the operand is written here at run time, from &4502
               JP SYS_GAP_BLOCK+&09            ; 4533 C3 9F 58

