;; --------------------------------------------------------------------
;; IS_LETTER -- &453C to &4549
;;
;; Takes:     A
;; Leaves:    F
;; Ends:      RET
;;
;; Shown for this routine in disasm/:
;;
;;     Carry set if A is a letter, clear if it is not.
;;     
;;     Four compares with CCF between them, bracketing "A" to "Z" and then
;;     "a" to "z".  Nothing else is accepted, so a digit or an underscore
;;     fails -- which is why the callers that scan a name test the first
;;     character with this and later characters with something looser.
;; --------------------------------------------------------------------

; ---- IS_LETTER ---- from &454A, &4CE6, &4E1E, &567C, &57BE, &5844
IS_LETTER:
               CP &41                          ; 453C FE 41
               CCF                             ; 453E 3F
               RET NC                          ; 453F D0
               CP &5B                          ; 4540 FE 5B
               RET C                           ; 4542 D8
               CP &61                          ; 4543 FE 61
               CCF                             ; 4545 3F
               RET NC                          ; 4546 D0
               CP &7B                          ; 4547 FE 7B
               RET                             ; 4549 C9

