MULTIPLY_BY_24:
               LD B,H                          ; 45F9 44
               LD C,L                          ; 45FA 4D
               ADD HL,HL                       ; 45FB 29
               ADD HL,BC                       ; 45FC 09
               ADD HL,HL                       ; 45FD 29
               ADD HL,HL                       ; 45FE 29
               ADD HL,HL                       ; 45FF 29
               ADC A,A                         ; 4600 8F
               ADD HL,BC                       ; 4601 09
               ADC A,&00                       ; 4602 CE 00
               ADD HL,HL                       ; 4604 29
               ADC A,A                         ; 4605 8F
               ADD HL,HL                       ; 4606 29
               ADC A,A                         ; 4607 8F
               INC DE                          ; 4608 13
               EX DE,HL                        ; 4609 EB
               RET                             ; 460A C9

;; --------------------------------------------------------------------
;; CMD_SORT -- &460B to &4618
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls CALL_NEXTCHAR; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     SORT -- the SORT command, token 251.
;;     
;;         SORT [ABS] [INVERSE] a$
;;     
;;     Sorts the strings of a string array, or the characters of a plain
;;     string, in place.  Plain SORT ignores case: bit 5 of each character's
;;     code is not considered.  ABS sorts strictly by character code, which is
;;     what SVAL$-packed numbers need, and is slightly faster.  INVERSE
;;     reverses the order.
;;     
;;     Two slicers are allowed: the first selects which strings to sort, the
;;     second which part of each string to compare on, so SORT a$()(2 TO )
;;     orders the whole array on everything but the first character.
;;     
;;     Manual: "Sorting data".
;; --------------------------------------------------------------------

CMD_SORT:
               CALL CALL_NEXTCHAR              ; 460B CD 61 44
               LD (V4098),A                    ; 460E 32 98 40
               INC A                           ; 4611 3C
               JR NZ,CMD_SORT_1                ; 4612 20 05
               CALL CALL_NEXTCHAR              ; 4614 CD 61 44
               CP &5B                          ; 4617 FE 5B

