               ; to the alternate register set and back again
               EX AF,AF'                       ; 46C2 08
               IN A,(HMPR)                     ; 46C3 DB FB
               ADD A,&02                       ; 46C5 C6 02
               OUT (HMPR),A                    ; 46C7 D3 FB
               ; to the alternate register set and back again
               EX AF,AF'                       ; 46C9 08
               SET 7,H                         ; 46CA CB FC
               RET                             ; 46CC C9

