;;     Put the other half of the image at &8000 and return the old HMPR.
;;     
;;     &42CD is the byte the boot sector patched with the other page's
;;     number less one, so reading it and adding one gives that page.  The
;;     PUSH AF at the top and the POP AF at the bottom are not saving the
;;     port across the call -- they are how the old value gets back into A
;;     to be returned, for the caller to put back later.
;; --------------------------------------------------------------------

; ---- PAGE_IN_OTHER_HALF ---- from &4906, &49A3, &4A0D, &4A3A, &4A7F
PAGE_IN_OTHER_HALF:
               IN A,(HMPR)                     ; 49D1 DB FB
               PUSH AF                         ; 49D3 F5
               LD A,(&42CD)                    ; 49D4 3A CD 42
               INC A                           ; 49D7 3C
               OUT (HMPR),A                    ; 49D8 D3 FB
               POP AF                          ; 49DA F1
               RET                             ; 49DB C9

