               CP &3A                          ; 49E6 FE 3A
               JR NC,PORT_BCD_DIGIT_1          ; 49E8 30 0C
               LD (HL),A                       ; 49EA 77
               JR PORT_BCD_DIGIT_1             ; 49EB 18 09

