;;     falls back on V40AD.
;; --------------------------------------------------------------------

; ---- PARSE_OPTIONAL_RANGE ---- from &5DAB
PARSE_OPTIONAL_RANGE:
               NOP                             ; 4B5B 00

;; --------------------------------------------------------------------
;; FN_INARRAY_1 -- &4B5C to &4B7C
