               EXX                             ; 4BB4 D9
               LD C,A                          ; 4BB5 4F
               ; to the alternate register set and back again
               EXX                             ; 4BB6 D9
               POP BC                          ; 4BB7 C1
               DEC BC                          ; 4BB8 0B
               POP HL                          ; 4BB9 E1
               SCF                             ; 4BBA 37
               SBC HL,BC                       ; 4BBB ED 42
               INC HL                          ; 4BBD 23

;; --------------------------------------------------------------------
;; PARSE_OPTIONAL_RANGE_LOOP2 -- &4BBE to &4BD6
;;
;; Takes:     BC, HL
;; Leaves:    A, F, DE
;; Preserves: BC, HL (saved and restored)
;; Ends:      JR
