               RES 7,H                         ; 4BC6 CB BC
               LD A,H                          ; 4BC8 7C
               OR L                            ; 4BC9 B5
               JR Z,PARSE_OPTIONAL_RANGE_6     ; 4BCA 28 4C
               LD DE,&0000                     ; 4BCC 11 00 00
               LD (V40A4),DE                   ; 4BCF ED 53 A4 40
               INC DE                          ; 4BD3 13
               PUSH DE                         ; 4BD4 D5
