               LD A,B                          ; 4C31 78
               AND A                           ; 4C32 A7
               JP NZ,PARSE_OPTIONAL_RANGE_LOOP ; 4C33 C2 A3 4B
               LD A,C                          ; 4C36 79
               LD (V4098),A                    ; 4C37 32 98 40
               AND A                           ; 4C3A A7
               RET Z                           ; 4C3B C8
               EX DE,HL                        ; 4C3C EB
               LD DE,INSTALL_ROM_PATCHES       ; 4C3D 11 00 7B  &7B00 is the installer's own code, dead since boot: this is the search-string buffer
               LDIR                            ; 4C40 ED B0
               RET                             ; 4C42 C9

