               RES 7,D                         ; 4C60 CB BA
               ADD HL,DE                       ; 4C62 19
               ADC A,&00                       ; 4C63 CE 00
               ; call DOS_EPCOM_LOOP-&4000 in the other page: LMPR is switched first, so that address is how the other listing numbers it
               CALL CALLDOS                    ; 4C65 CD C1 42
               DEFW DOS_EPCOM_LOOP-&4000      ; 4C68 C4 65
               RET                             ; 4C6A C9

;; --------------------------------------------------------------------
;; STACK_PAGE0_STRING -- &4C6B to &4C75
;;
;; Takes:     A, BC, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? reaches the ROM through STKSTR; calls CMR; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     Stack a string descriptor for a block in page 0.
;;     
;;     The ROM's STKSTORE wants the page in A, the address in DE and the
;;     length in BC.  This builds them from two bytes: the address becomes
;;     C times 256 and the length the old B, with the page forced to zero.
;;     A whole-page-aligned block in the system page is what that describes.
;; --------------------------------------------------------------------

; ---- STACK_PAGE0_STRING ---- from &41DB, &4B48, &4C45, &4D6A, &4DC6, &4E7E
STACK_PAGE0_STRING:
               XOR A                           ; 4C6B AF
               LD E,A                          ; 4C6C 5F
               LD D,C                          ; 4C6D 51
               LD C,B                          ; 4C6E 48
               LD B,A                          ; 4C6F 47
               ; call the ROM at STKSTR with ROM1 paged in, and page back on the way out
               CALL CMR                        ; 4C70 CD F0 44
               DEFW STKSTR                    ; 4C73 27 01
               RET                             ; 4C75 C9

;; --------------------------------------------------------------------
;; GET_PAGED_ADDRESS -- &4C76 to &4C82
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls GET_LONG_INTEGER; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     An address argument that may run past 64K.  GET_LONG_INTEGER gives 32
;;     bits, anything in D is "Integer out of range", and what is left is
;;     shifted three places -- RL H with RLA, three times, to carry the top
;;     bits into the page, then three RR H with a SCF before the last, which
;;     puts the address back in a section with its top bit set.
;; --------------------------------------------------------------------

; ---- GET_PAGED_ADDRESS ---- from &4B04, &4B16
GET_PAGED_ADDRESS:
               CALL GET_LONG_INTEGER           ; 4C76 CD 92 44
               LD A,D                          ; 4C79 7A
               AND A                           ; 4C7A A7
               JP NZ,REP_INTEGER_OUT_OF_RANGE  ; 4C7B C2 A7 43
               LD A,E                          ; 4C7E 7B
               LD H,B                          ; 4C7F 60
               LD L,C                          ; 4C80 69
               LD B,&03                        ; 4C81 06 03

;; --------------------------------------------------------------------
