               CP C                            ; 4CBF B9
               ; to the alternate register set and back again
               EXX                             ; 4CC0 D9
               JR Z,SEARCH_MEMORY_LOOP2        ; 4CC1 28 F0
               LD DE,INSTALL_ROM_PATCHES       ; 4CC3 11 00 7B
               POP HL                          ; 4CC6 E1
               POP AF                          ; 4CC7 F1
               JR SEARCH_MEMORY_LOOP           ; 4CC8 18 E0

;; --------------------------------------------------------------------
;; L4CCA -- &4CCA to &4CD0
