               LD B,A                          ; 5A03 47
               IN A,(LMPR)                     ; 5A04 DB FA
               LD C,A                          ; 5A06 4F
               LD A,(&8008)                    ; 5A07 3A 08 80
               PUSH AF                         ; 5A0A F5

