               LD A,&F7                        ; 5B75 3E F7
               IN A,(STAT)                     ; 5B77 DB F9
               AND &20                         ; 5B79 E6 20
               RET NZ                          ; 5B7B C0
               LD A,&54                        ; 5B7C 3E 54  error 84, "Escape requested"
               JP REPORT                       ; 5B7E C3 BE 43

