;; --------------------------------------------------------------------
;; PREPARE_ROM1_COPY -- &5C4B to &5C4E
;;
;; Takes:     DE, HL
;; Leaves:    DE, HL
;;
;; Shown for this routine in disasm/:
;;
;;     Set up to copy one of the ROM's own ROM 1 routines into the system
;;     page.  DE points at a command table entry; the word after its first
;;     byte is the routine's address.  B is loaded with &E7 -- RST &20, the
;;     ROM's next-character restart -- and PAGE_IN_ROM1 plants it at the
;;     destination, so every copy begins by fetching a character.  It comes
;;     back with HL at the source, DE one past the planted byte, and the old
;;     HMPR in A.
;; --------------------------------------------------------------------

; ---- PREPARE_ROM1_COPY ---- from &5D65, &5D7B, DOS &6F6E
PREPARE_ROM1_COPY:
               PUSH HL                         ; 5C4B E5
               INC DE                          ; 5C4C 13
               EX DE,HL                        ; 5C4D EB
               LD E,(HL)                       ; 5C4E 5E

;; --------------------------------------------------------------------
;; PREPARE_ROM1_COPY_1 -- &5C4F to &5C50
;;
;; Takes:     HL
;; Leaves:    D, HL
;; --------------------------------------------------------------------

; ---- PREPARE_ROM1_COPY_1 ---- from DOS &68AB, DOS &69C1, DOS &6D28, DOS &6DF0, DOS &6E5D, DOS &7020
PREPARE_ROM1_COPY_1:
               INC HL                          ; 5C4F 23
               LD D,(HL)                       ; 5C50 56

;; --------------------------------------------------------------------
;; PREPARE_ROM1_COPY_2 -- &5C51 to &5C55
;;
;; Takes:     nothing in registers
;; Leaves:    B, HL
;; Ends:      JR
;; --------------------------------------------------------------------

; ---- PREPARE_ROM1_COPY_2 ---- from DOS &6852, DOS &691C, DOS &691F, DOS &6943, DOS &6981
PREPARE_ROM1_COPY_2:
               LD B,&E7                        ; 5C51 06 E7
               POP HL                          ; 5C53 E1
               JR PAGE_IN_ROM1                 ; 5C54 18 03

;; --------------------------------------------------------------------
;; PREPARE_COPY_AT_5000 -- &5C56 to &5C58
;;
;; Takes:     nothing in registers
;; Leaves:    HL
