; ---- PREPARE_COPY_AT_5000 ---- from &5CC3, &5D34
PREPARE_COPY_AT_5000:
               LD HL,&9000                     ; 5C56 21 00 90

;; --------------------------------------------------------------------
;; PAGE_IN_ROM1 -- &5C59 to &5C64
;;
;; Takes:     nothing in registers
;; Leaves:    A, F, C
;;
;; ? drives IN A,(HMPR), IN A,(LMPR); falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     Set bit 6 of LMPR, which pages ROM1 in, and save the old HMPR in C.
;;     
;;     The ROM's own source names that bit where it does the same thing:
;;     "OR &40 -- BIT FOR ROM1=HI (ACTIVE)".
;; --------------------------------------------------------------------

; ---- PAGE_IN_ROM1 ---- from &5C54, &5CE4
PAGE_IN_ROM1:
               IN A,(LMPR)                     ; 5C59 DB FA
               OR ENABLE_ROM1                  ; 5C5B F6 40
               OUT (LMPR),A                    ; 5C5D D3 FA
               IN A,(HMPR)                     ; 5C5F DB FB
               LD C,A                          ; 5C61 4F
               XOR A                           ; 5C62 AF
               OUT (HMPR),A                    ; 5C63 D3 FB

;; --------------------------------------------------------------------
;; PAGE_IN_ROM1_1 -- &5C65 to &5C69
;;
;; Takes:     BC, DE, HL
;; Leaves:    A, DE, HL
;; Ends:      RET
;; --------------------------------------------------------------------

PAGE_IN_ROM1_1:
               LD A,C                          ; 5C65 79
               LD (HL),B                       ; 5C66 70
               INC HL                          ; 5C67 23
               EX DE,HL                        ; 5C68 EB
               RET                             ; 5C69 C9

;; --------------------------------------------------------------------
;; CMD_SOUND -- &5C6A to &5C9C
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;; Ends:      RET
;;
;; ? tests for T_CLEAR, CH_COLON, CH_CR; calls CALL_NEXTCHAR, NUMBER_THEN_END, SILENCE_SOUND_CHIP, GET_BUFFER_SIZE.
;;
;; Shown for this routine in disasm/:
;;
;;     SOUND, token &AE -- and the reason for taking it over is in the
;;     manual, which documents SOUND CLEAR and SOUND CLEAR size:
;;     
;;     "SOUND CLEAR used on its own will clear the buffer ... To change
;;     the sound buffer size, simply use SOUND CLEAR with a different
;;     value.  SOUND CLEAR 0 will delete the buffer and free the memory
;;     for other uses."
;;     
;;     The code is that sentence.  The next character is compared with the
;;     ROM's CLEAR token and anything else leaves for L5CC1, the ordinary
;;     SOUND; a colon or carriage return goes to L5C9D, which is SOUND CLEAR
;;     with no argument; otherwise a number is read and the buffer is
;;     reallocated -- FREE_SLOT_CHAIN gives the old one back if there was
;;     one, and the new page and address are written to four XVARs.
;; --------------------------------------------------------------------

; ---- CMD_SOUND ---- from &4ECC when A = &AE
CMD_SOUND:
               CALL CALL_NEXTCHAR              ; 5C6A CD 61 44
               CP T_CLEAR                      ; 5C6D FE B3
               JP NZ,CMD_SOUND_2               ; 5C6F C2 C1 5C
               CALL CALL_NEXTCHAR              ; 5C72 CD 61 44
               CP CH_COLON                     ; 5C75 FE 3A
               JR Z,CMD_SOUND_1                ; 5C77 28 24
               CP CH_CR                        ; 5C79 FE 0D
               JR Z,CMD_SOUND_1                ; 5C7B 28 20
               CALL NUMBER_THEN_END            ; 5C7D CD C8 44
               CALL SILENCE_SOUND_CHIP         ; 5C80 CD A0 5C
               LD A,(V407E)                    ; 5C83 3A 7E 40
               LD HL,(V407F)                   ; 5C86 2A 7F 40
               AND A                           ; 5C89 A7
               CALL NZ,FREE_SLOT_CHAIN         ; 5C8A C4 7B 5F
               CALL GET_BUFFER_SIZE            ; 5C8D CD DD 5E
               LD (V407E),A                    ; 5C90 32 7E 40
               LD (V407F),HL                   ; 5C93 22 7F 40
               LD (V4081),A                    ; 5C96 32 81 40
               LD (V4082),HL                   ; 5C99 22 82 40
               RET                             ; 5C9C C9

;; --------------------------------------------------------------------
;; CMD_SOUND_1 -- &5C9D to &5C9F
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls EXPECT_END_OF_STATEMENT; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- CMD_SOUND_1 ---- from &5C77 when A = &3A, &5C7B when A = &0D
CMD_SOUND_1:
               CALL EXPECT_END_OF_STATEMENT    ; 5C9D CD D0 44

;; --------------------------------------------------------------------
;; SILENCE_SOUND_CHIP -- &5CA0 to &5CB3
;;
;; Takes:     A
;; Leaves:    A, F, HL
;;
;; Shown for this routine in disasm/:
;;
;;     Write zero to all thirty-two of the sound chip's registers, from 31
;;     down to 0.  The listing's own equate says how: SOUND is &FF, "write:
;;     sound data, the sound address port being &1FF", and the loop uses one
;;     register pair for both:
;;     
;;     LD BC,&01FF : DEC A : OUT (C),A     select register A at &1FF
;;     DEC B       : OUT (C),B             write zero to it at &00FF
;;     
;;     DEC B turns the address port into the data port and supplies the zero
;;     at the same time.  Before the loop it waits for a frame with EI :
;;     HALT and puts the buffer pointers back, which is SOUND CLEAR's
;;     "clear the buffer" -- CMD_SOUND calls it from &5C80.
;; --------------------------------------------------------------------

; ---- SILENCE_SOUND_CHIP ---- from &5C80
SILENCE_SOUND_CHIP:
               EI                              ; 5CA0 FB
               HALT                            ; 5CA1 76
               XOR A                           ; 5CA2 AF
               LD (V4084),A                    ; 5CA3 32 84 40
               LD HL,(V407F)                   ; 5CA6 2A 7F 40
               LD (V4082),HL                   ; 5CA9 22 82 40
               LD A,(V407E)                    ; 5CAC 3A 7E 40
               LD (V4081),A                    ; 5CAF 32 81 40
               LD A,&20                        ; 5CB2 3E 20

;; --------------------------------------------------------------------
;; SILENCE_SOUND_CHIP_LOOP -- &5CB4 to &5CC0
;;
;; Takes:     A
;; Leaves:    A, F, BC
;; Ends:      RET
;;
;; ? drives OUT (C),A, OUT (C),B.
;; --------------------------------------------------------------------

; ---- SILENCE_SOUND_CHIP_LOOP ---- from &5CBE when A <> 0
SILENCE_SOUND_CHIP_LOOP:
               LD BC,&01FF                     ; 5CB4 01 FF 01
               DEC A                           ; 5CB7 3D
               OUT (C),A                       ; 5CB8 ED 79
               DEC B                           ; 5CBA 05
               OUT (C),B                       ; 5CBB ED 41
               AND A                           ; 5CBD A7
               JR NZ,SILENCE_SOUND_CHIP_LOOP   ; 5CBE 20 F4
               RET                             ; 5CC0 C9

;; --------------------------------------------------------------------
;; CMD_SOUND_2 -- &5CC1 to &5CDE
;;
;; Takes:     A, DE, HL
;; Leaves:    BC, DE, HL
;; Preserves: A, F (saved and restored)
