               PUSH HL                         ; 5CCB E5
               LD HL,V5DBF                     ; 5CCC 21 BF 5D
               LD C,&0B                        ; 5CCF 0E 0B
               LDIR                            ; 5CD1 ED B0
               POP HL                          ; 5CD3 E1
               LD C,&12                        ; 5CD4 0E 12
               LDIR                            ; 5CD6 ED B0
               LD HL,SILENCE_SOUND_CHIP_2      ; 5CD8 21 E7 5D
