;; --------------------------------------------------------------------
;; BUILD_PAGE_IN_TRAMPOLINE -- &5CDF to &5D1F
;;
;; Takes:     A, DE
;; Leaves:    BC, DE, HL
;; Preserves: A, F (saved and restored)
;; Ends:      JP, JR
;;
;; ? drives IN A,(LMPR), OUT (HMPR),A; calls PAGE_IN_ROM1.
;;
;; Shown for this routine in disasm/:
;;
;;     Assemble a short routine in the ROM's code buffer whose whole job is
;;     to page MasterBASIC in and jump into it.
;;     
;;     It first copies nine bytes from &4D50 in the system page -- which is
;;     CDBUFF+&50, where hook 185 builds -- and then writes the rest a byte
;;     at a time, opcode by opcode:
;;     
;;     C2 00 00      JP NZ,&0000     the operand is filled in later
;;     D0            RET NC
;;     3E nn         LD A,page       LMPR+1, this half's own page
;;     D3 FB         OUT (HMPR),A
;;     21 nn nn      LD HL,DE        the caller's DE
;;     C3 20 9D      JP &9D20
;;     
;;     &9D20 is in the window, so it is this half's &5D20 seen from a page
;;     where this half sits at &8000.  The trampoline therefore pages
;;     MasterBASIC into the window and jumps straight into it, carrying HL.
;;     
;;     Finally LD BC,&4D50 and a fall into RESTORE_HMPR_AND_STORE, which
;;     puts HMPR back and writes &4D50 -- the address of what was just
;;     built -- through the pointer in V4076, so whoever needs the
;;     trampoline can find it.
;;     
;;     That is the third builder into CDBUFF, after &735D at +&11 and hook
;;     185 at +&50.  This one lands at +&50 as well, so it and the hook are
;;     alternative users of the same space rather than both being live.
;; --------------------------------------------------------------------

; ---- BUILD_PAGE_IN_TRAMPOLINE ---- from &4EB8 when A = &E1
BUILD_PAGE_IN_TRAMPOLINE:
               LD B,&E7                        ; 5CDF 06 E7
               LD HL,&8D50                     ; 5CE1 21 50 8D
               CALL PAGE_IN_ROM1               ; 5CE4 CD 59 5C
               PUSH AF                         ; 5CE7 F5
               LD BC,&0009                     ; 5CE8 01 09 00
               LDIR                            ; 5CEB ED B0
               EX DE,HL                        ; 5CED EB
               LD (HL),&C2                     ; 5CEE 36 C2
               INC HL                          ; 5CF0 23

L5CF1:
               LD BC,&0000                     ; 5CF1 01 00 00  the operand is written here at run time, from &79BA
               LD (HL),C                       ; 5CF4 71
               INC HL                          ; 5CF5 23
               LD (HL),B                       ; 5CF6 70
               INC HL                          ; 5CF7 23
               LD (HL),&D0                     ; 5CF8 36 D0
               INC HL                          ; 5CFA 23
               LD (HL),&3E                     ; 5CFB 36 3E
               INC HL                          ; 5CFD 23
               IN A,(LMPR)                     ; 5CFE DB FA
               INC A                           ; 5D00 3C
               AND PAGEMASK                    ; 5D01 E6 1F
               LD (HL),A                       ; 5D03 77
               INC HL                          ; 5D04 23
               LD (HL),&D3                     ; 5D05 36 D3
               INC HL                          ; 5D07 23
               LD (HL),&FB                     ; 5D08 36 FB
               INC HL                          ; 5D0A 23
               LD (HL),&21                     ; 5D0B 36 21
               INC HL                          ; 5D0D 23
               LD (HL),E                       ; 5D0E 73
               INC HL                          ; 5D0F 23
               LD (HL),D                       ; 5D10 72
               INC HL                          ; 5D11 23
               LD (HL),&C3                     ; 5D12 36 C3
               INC HL                          ; 5D14 23
               LD BC,&9D20                     ; 5D15 01 20 9D
               LD (HL),C                       ; 5D18 71
               INC HL                          ; 5D19 23
               LD (HL),B                       ; 5D1A 70
               LD BC,&4D50                     ; 5D1B 01 50 4D
               JR RESTORE_HMPR_AND_STORE       ; 5D1E 18 3C

;; --------------------------------------------------------------------
;; L5D20 -- &5D20 to &5D31
;;
;; Takes:     HL
;; Leaves:    A, F, BC, DE, HL, IY
;; Ends:      JP
;;
;; ? calls EXPECT_COMMA, EXPECT_RPAREN, CALL_EXPSTR, TWO_PAGED_STRINGS.
;; --------------------------------------------------------------------
               LD DE,SYS_CDBUFF_50             ; 5D20 11 50 4D  where the trampoline lands, with this half paged in at &8000
               LD BC,&0015                     ; 5D23 01 15 00
               LDIR                            ; 5D26 ED B0
               LD HL,COPY_THEN_APPEND_CALL_6+&4000 ; 5D28 21 1F 9E
               LD C,&45                        ; 5D2B 0E 45
               LDIR                            ; 5D2D ED B0
               JP &4D53                        ; 5D2F C3 53 4D

;; --------------------------------------------------------------------
;; CMD_PAUSE -- &5D32 to &5D56
;;
;; Takes:     A, DE, HL
;; Leaves:    A, F, BC, DE, HL
;;
;; ? calls PREPARE_COPY_AT_5000; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     PAUSE, token &C2.  It parses nothing: it builds.  L5C56 puts &5000 in
;;     the system page in HL and PAGE_IN_ROM1 writes &E7 -- RST &20, the
;;     ROM's next-character restart -- as the first byte, then six bytes are
;;     copied in, &F5 (PUSH AF) is planted, five more bytes, seven from
;;     L5DCA, sixteen more and &4E from L5DD1.
;;     
;;     The manual says why PAUSE and not just SOUND: with RECORD SOUND on,
;;     "the SOUNDs and the PAUSEs that determine their length" both have to
;;     add codes to the string being recorded, so PAUSE needs a hook of its
;;     own.
;; --------------------------------------------------------------------

; ---- CMD_PAUSE ---- from &4EBD when A = &C2
CMD_PAUSE:
               LD B,&E7                        ; 5D32 06 E7
               CALL PREPARE_COPY_AT_5000       ; 5D34 CD 56 5C
               PUSH AF                         ; 5D37 F5
               LD BC,&0006                     ; 5D38 01 06 00
               LDIR                            ; 5D3B ED B0
               LD A,&F5                        ; 5D3D 3E F5
               LD (DE),A                       ; 5D3F 12
               INC DE                          ; 5D40 13
               LD C,&05                        ; 5D41 0E 05
               LDIR                            ; 5D43 ED B0
               PUSH HL                         ; 5D45 E5
               LD HL,CMD_PAUSE_1               ; 5D46 21 CA 5D
               LD C,&07                        ; 5D49 0E 07
               LDIR                            ; 5D4B ED B0
               POP HL                          ; 5D4D E1
               LD C,&10                        ; 5D4E 0E 10
               LDIR                            ; 5D50 ED B0
               LD HL,CMD_PAUSE_2               ; 5D52 21 D1 5D
               LD C,&4E                        ; 5D55 0E 4E

