;; --------------------------------------------------------------------
;; CMD_DEF_KEYCODE -- &5D62 to &5D77
;;
;; Takes:     A, DE
;; Leaves:    BC, DE, HL
;; Preserves: A, F (saved and restored)
;; Ends:      JP, JR
;;
;; ? drives OUT (HMPR),A; calls PREPARE_ROM1_COPY.
;;
;; Shown for this routine in disasm/:
;;
;;     DEF KEYCODE, token &C9.  &8F00 is the ROM's &4F00 seen through the
;;     window PAGE_IN_ROM1 is about to open; L5C4B picks the routine's real
;;     address out of the two bytes after the table entry, and &91 bytes are
;;     copied there behind an &E7.  Then &4A9F -- an address in the second
;;     installed stub in that page -- is written into &4F0D, and &4F00 is
;;     handed to STORE_BC_AT_XVAR76.
;;     
;;     The ROM's own source settles what this is.  ref/samrom/miscx2.asm
;;     opens
;;     
;;     ORG INSTBUF
;;     DKP2:  CALL EXPT1NUM   ;NUMBER OF KEY CODE TO DEFINE
;;     
;;     -- so DEF KEYCODE is one of the ROM 1 routines the ROM assembles to
;;     run at INSTBUF and copies there when the command is used, and DKLN,
;;     the length it copies, is DKFIN+1-DKP2.  MasterBASIC does the ROM's
;;     own copy for it, prefixes an RST &20 and changes one operand.
;; --------------------------------------------------------------------

; ---- CMD_DEF_KEYCODE ---- from &4EC2 when A = &C9
CMD_DEF_KEYCODE:
               LD HL,&8F00                     ; 5D62 21 00 8F
               CALL PREPARE_ROM1_COPY          ; 5D65 CD 4B 5C
               PUSH AF                         ; 5D68 F5
               LD BC,&0091                     ; 5D69 01 91 00
               LDIR                            ; 5D6C ED B0
               LD HL,&4A9F                     ; 5D6E 21 9F 4A
               LD (&8F0D),HL                   ; 5D71 22 0D 8F
               LD B,&4F                        ; 5D74 06 4F
               JR RESTORE_HMPR_AND_STORE       ; 5D76 18 E4

;; --------------------------------------------------------------------
;; CMD_KEYIN -- &5D78 to &5D9E
;;
;; Takes:     A, DE
;; Leaves:    BC, DE, HL
;; Preserves: A, F (saved and restored)
;; Ends:      JP, JR
;;
;; ? drives OUT (HMPR),A; calls PREPARE_ROM1_COPY, COPY_THEN_APPEND_CALL.
;;
;; Shown for this routine in disasm/:
;;
;;     KEYIN, token &D1.  The same shape, into HDR at &4B00: three runs of
;;     &09, &16 and &2C bytes, each followed by a three-byte CALL that
;;     COPY_THEN_APPEND_CALL adds, then six more and the seventeen at
;;     L5DAE, and &4B00 is handed on.
;;     
;;     The ROM's source settles this one too -- ref/samrom/miscx1.asm has
;;     
;;     ORG HDR
;;     KEYP2:  CALL SYNTAXA
;;     
;;     so KEYIN is assembled to run in the fifty-byte header buffer, which
;;     is free because KEYIN cannot be loading a file at the same time.
;;     MasterBASIC copies it there in three pieces and interposes a call
;;     after each, where DEF KEYCODE needed one patched operand.
;; --------------------------------------------------------------------

; ---- CMD_KEYIN ---- from &4EC7 when A = &D1
CMD_KEYIN:
               LD HL,&8B00                     ; 5D78 21 00 8B
               CALL PREPARE_ROM1_COPY          ; 5D7B CD 4B 5C
               PUSH AF                         ; 5D7E F5
               LD BC,&0009                     ; 5D7F 01 09 00
               CALL COPY_THEN_APPEND_CALL      ; 5D82 CD 9F 5D
               LD C,&16                        ; 5D85 0E 16
               CALL COPY_THEN_APPEND_CALL      ; 5D87 CD 9F 5D
               LD C,&2C                        ; 5D8A 0E 2C
               CALL COPY_THEN_APPEND_CALL      ; 5D8C CD 9F 5D
               LD C,&06                        ; 5D8F 0E 06
               LDIR                            ; 5D91 ED B0
               LD HL,CMD_KEYIN_1               ; 5D93 21 AE 5D
               LD C,&11                        ; 5D96 0E 11
               LDIR                            ; 5D98 ED B0
               LD BC,HDR                       ; 5D9A 01 00 4B
               JR RESTORE_HMPR_AND_STORE       ; 5D9D 18 BD

;; --------------------------------------------------------------------
;; COPY_THEN_APPEND_CALL -- &5D9F to &5DAA
;;
;; Takes:     BC, DE, HL
;; Leaves:    F, BC, DE
;; Preserves: HL (saved and restored)
;; Ends:      RET
;;
;; Shown for this routine in disasm/:
;;
;;     Do the caller's LDIR, then append three bytes that are a CALL.
;;     
;;     The three bytes at &5DAB are CD 5B 4B -- CALL &4B5B -- so whatever
;;     was just copied is finished off with a call to that address.  It is
;;     another of this image's run-time code builders, and the smallest:
;;     the caller supplies the body, this supplies the ending.  HL is
;;     preserved across the appended copy so the caller still has the end of
;;     its own block.
;; --------------------------------------------------------------------

; ---- COPY_THEN_APPEND_CALL ---- from &5D82, &5D87, &5D8C
COPY_THEN_APPEND_CALL:
               LDIR                            ; 5D9F ED B0
               PUSH HL                         ; 5DA1 E5
               LD HL,COPY_THEN_APPEND_CALL_1   ; 5DA2 21 AB 5D
               LD C,&03                        ; 5DA5 0E 03
               LDIR                            ; 5DA7 ED B0
               POP HL                          ; 5DA9 E1
               RET                             ; 5DAA C9

;; --------------------------------------------------------------------
;; COPY_THEN_APPEND_CALL_1 -- &5DAB to &5DAD
;;
;; Takes:     nothing in registers
