               CALL CHECK_BREAK_6+&4000        ; 5FDD CD E1 A0
               LD A,&3A                        ; 5FE0 3E 3A
               CALL CHECK_BREAK_2+&4000        ; 5FE2 CD 2A A0
               LD A,(SUBPPC)                   ; 5FE5 3A 47 5C
               LD HL,CHECK_BREAK_10+&4000      ; 5FE8 21 14 A1
               LD C,A                          ; 5FEB 4F
               LD B,&00                        ; 5FEC 06 00
               CALL CHECK_BREAK_7+&4000        ; 5FEE CD E4 A0
