               PUSH AF                         ; 65F6 F5
               LD DE,PUTSWA                    ; 65F7 11 00 40
               CALL SET_UP_WORK_AREA           ; 65FA CD 0A 66
               POP AF                          ; 65FD F1
               INC A                           ; 65FE 3C
               OUT (HMPR),A                    ; 65FF D3 FB
               POP HL                          ; 6601 E1
               POP DE                          ; 6602 D1
               POP AF                          ; 6603 F1
               DEC A                           ; 6604 3D
               JR NZ,COMPRESS_FILE_LOOP        ; 6605 20 EA

