;; ? drives OUT (HMPR),A.
;; --------------------------------------------------------------------

; ---- GET_WORK_PAGE_1 ---- from &67E2 when B is not 0 yet
GET_WORK_PAGE_1:
               LD (V40AA),A                    ; 67E8 32 AA 40
               POP DE                          ; 67EB D1
               POP AF                          ; 67EC F1
               OUT (HMPR),A                    ; 67ED D3 FB
               RET                             ; 67EF C9

;; --------------------------------------------------------------------
