               DEFW DOS_PLNS-&4000            ; 67F3 8E 50
               CALL CALL_NEXTCHAR              ; 67F5 CD 61 44
               LD HL,CMD_DUMP_21               ; 67F8 21 89 69
               LD (HL),&00                     ; 67FB 36 00
               CP T_INVERSE                    ; 67FD FE A5
               JR NZ,CMD_DUMP_1                ; 67FF 20 05
               LD (HL),&2F                     ; 6801 36 2F
               CALL CALL_NEXTCHAR              ; 6803 CD 61 44

