               DEC A                           ; 6A06 3D
               JR Z,SCREEN_PIXEL_COLOUR        ; 6A07 28 0A
               DEC A                           ; 6A09 3D
               LD A,C                          ; 6A0A 79
               LD C,B                          ; 6A0B 48
               LD B,A                          ; 6A0C 47
               JR Z,SCREEN_PIXEL_COLOUR        ; 6A0D 28 04

;; --------------------------------------------------------------------
;; TRANSFORM_DUMP_COORDS_1 -- &6A0F to &6A12
;;
;; Takes:     B
;; Leaves:    A, F, B
;; --------------------------------------------------------------------

; ---- TRANSFORM_DUMP_COORDS_1 ---- from &6A04 when A reaches 0
TRANSFORM_DUMP_COORDS_1:
               LD A,&BF                        ; 6A0F 3E BF
               SUB B                           ; 6A11 90
               LD B,A                          ; 6A12 47

;; --------------------------------------------------------------------
;; SCREEN_PIXEL_COLOUR -- &6A13 to &6A2C
;;
;; Takes:     BC
;; Leaves:    A, F, BC, H
;;
;; ? calls READ_PIXEL_NIBBLE; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     Read the colour of the pixel at BC, in whichever screen mode.
;;     
;;     Four modes, three ways of storing a pixel, so this splits three
;;     ways on DUMP_MODE:
;;     
;;     0, 1   MODE 1 and 2, a bitmap with attributes elsewhere
;;     2      MODE 3, four pixels to a byte
;;     3      MODE 4, two pixels to a byte
;;     
;;     MODE 4 is READ_PIXEL_NIBBLE by itself: the answer is a whole nibble
;;     and is already the colour.  MODE 3 reads the nibble the same way and
;;     then takes half of it, choosing which half by bit 0 of the row, and
;;     exchanges 1 and 2 on the way out -- the two bits come out of the
;;     byte in the opposite order from the palette index, and 0 and 3 are
;;     the same either way round, which is why only the middle two move.
;; --------------------------------------------------------------------

; ---- SCREEN_PIXEL_COLOUR ---- from &6A07 when A reaches 0, &6A0D when A reaches 0, &6CF6, &6D02
SCREEN_PIXEL_COLOUR:
               LD A,(DUMP_MODE)                ; 6A13 3A AE 40
               CP &02                          ; 6A16 FE 02
               JR C,ATTRIBUTE_PIXEL_COLOUR     ; 6A18 38 2E
               JR NZ,READ_PIXEL_NIBBLE         ; 6A1A 20 1D
               LD H,C                          ; 6A1C 61
               LD A,(V40AA)                    ; 6A1D 3A AA 40
               SRL C                           ; 6A20 CB 39
               ADD A,C                         ; 6A22 81
               LD C,A                          ; 6A23 4F
               CALL READ_PIXEL_NIBBLE          ; 6A24 CD 39 6A
               BIT 0,H                         ; 6A27 CB 44
               JR NZ,SCREEN_PIXEL_COLOUR_1     ; 6A29 20 02
               RRCA                            ; 6A2B 0F
               RRCA                            ; 6A2C 0F

;; --------------------------------------------------------------------
;; SCREEN_PIXEL_COLOUR_1 -- &6A2D to &6A38
;;
;; Takes:     A
;; Leaves:    A, F
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- SCREEN_PIXEL_COLOUR_1 ---- from &6A29 when bit 0 of H set
SCREEN_PIXEL_COLOUR_1:
               AND &03                         ; 6A2D E6 03
               RET Z                           ; 6A2F C8
               CP &03                          ; 6A30 FE 03
               RET Z                           ; 6A32 C8
               DEC A                           ; 6A33 3D
               LD A,&02                        ; 6A34 3E 02
               RET Z                           ; 6A36 C8
               DEC A                           ; 6A37 3D
               RET                             ; 6A38 C9

;; --------------------------------------------------------------------
;; READ_PIXEL_NIBBLE -- &6A39 to &6A41
;;
;; Takes:     BC
;; Leaves:    A, F, BC
;;
;; Shown for this routine in disasm/:
;;
;;     Fetch the byte holding pixel BC and shift the wanted nibble down.
;;     
;;     SCF : RR B : RR C halves BC and sets bit 15 of it in one go, so the
;;     address is &8000 plus BC/2 -- two pixels to a byte, and the screen
;;     paged into the window.  The bit shifted out of C says which nibble,
;;     and the four RRCAs bring the high one down.
;; --------------------------------------------------------------------

; ---- READ_PIXEL_NIBBLE ---- from &6A1A, &6A24
READ_PIXEL_NIBBLE:
               SCF                             ; 6A39 37
               RR B                            ; 6A3A CB 18
               RR C                            ; 6A3C CB 19
               LD A,(BC)                       ; 6A3E 0A
               JR C,READ_PIXEL_NIBBLE_DONE     ; 6A3F 38 04
               RRCA                            ; 6A41 0F

;; --------------------------------------------------------------------
;; READ_PIXEL_NIBBLE_LOOP -- &6A42 to &6A44
;;
;; Takes:     A
;; Leaves:    A, F
;; --------------------------------------------------------------------

; ---- READ_PIXEL_NIBBLE_LOOP ---- from &6A5F when no bit of &01 is set
READ_PIXEL_NIBBLE_LOOP:
               RRCA                            ; 6A42 0F
               RRCA                            ; 6A43 0F
               RRCA                            ; 6A44 0F

;; --------------------------------------------------------------------
;; READ_PIXEL_NIBBLE_DONE -- &6A45 to &6A47
;;
;; Takes:     A
;; Leaves:    A, F
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- READ_PIXEL_NIBBLE_DONE ---- from &6A3F when bit 0 of C was set
READ_PIXEL_NIBBLE_DONE:
               AND &0F                         ; 6A45 E6 0F
               RET                             ; 6A47 C9

;; --------------------------------------------------------------------
;; ATTRIBUTE_PIXEL_COLOUR -- &6A48 to &6A4E
;;
;; Takes:     A, BC
;; Leaves:    A, F, B, HL
;;
;; ? calls MODE2_PIXEL_AND_ATTR; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     The MODE 1 and MODE 2 case: one bit of a bitmap, coloured by an
;;     attribute byte.
;;     
;;     MODE1_PIXEL_AND_ATTR or MODE2_PIXEL_AND_ATTR leaves the byte in B
;;     and its attribute in L.  The bit wanted is (C AND 7) + 1 rotations
;;     away, and the answer is L AND 7 for ink or L shifted down three for
;;     paper, with bit 6 of the attribute adding 8 for bright.
;; --------------------------------------------------------------------

; ---- ATTRIBUTE_PIXEL_COLOUR ---- from &6A18 when A < &02
ATTRIBUTE_PIXEL_COLOUR:
               AND A                           ; 6A48 A7
               JR Z,ATTRIBUTE_PIXEL_COLOUR_1   ; 6A49 28 04
               CALL MODE2_PIXEL_AND_ATTR       ; 6A4B CD 5D 6C
               SCF                             ; 6A4E 37

;; --------------------------------------------------------------------
;; ATTRIBUTE_PIXEL_COLOUR_1 -- &6A4F to &6A58
;;
;; Takes:     BC
;; Leaves:    A, F, B, HL
;;
;; ? calls MODE1_PIXEL_AND_ATTR; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- ATTRIBUTE_PIXEL_COLOUR_1 ---- from &6A49 when A = 0
ATTRIBUTE_PIXEL_COLOUR_1:
               CALL NC,MODE1_PIXEL_AND_ATTR    ; 6A4F D4 2F 6C
               LD A,C                          ; 6A52 79
               AND &07                         ; 6A53 E6 07
               INC A                           ; 6A55 3C
               LD H,A                          ; 6A56 67
               LD A,B                          ; 6A57 78
               LD B,H                          ; 6A58 44

;; --------------------------------------------------------------------
;; ATTRIBUTE_PIXEL_COLOUR_LOOP -- &6A59 to &6A68
;;
;; Takes:     A, B, L
;; Leaves:    A, F, B
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- ATTRIBUTE_PIXEL_COLOUR_LOOP ---- from &6A5A when B is not 0 yet
ATTRIBUTE_PIXEL_COLOUR_LOOP:
               RLCA                            ; 6A59 07
               DJNZ ATTRIBUTE_PIXEL_COLOUR_LOOP ; 6A5A 10 FD
               AND &01                         ; 6A5C E6 01
               LD A,L                          ; 6A5E 7D
               JR Z,READ_PIXEL_NIBBLE_LOOP     ; 6A5F 28 E1
               AND &07                         ; 6A61 E6 07
               BIT 6,L                         ; 6A63 CB 75
               RET Z                           ; 6A65 C8
               OR &08                          ; 6A66 F6 08
               RET                             ; 6A68 C9

;; --------------------------------------------------------------------
;; BUILD_GREY_MAP -- &6A69 to &6A6D
;;
;; Takes:     nothing in registers
;; Leaves:    B, HL
;;
;; Shown for this routine in disasm/:
;;
;;     Give each of the sixteen palette colours a grey level to print as.
;;     
;;     Twenty-five levels, one byte each at &7B90 marking whether that
;;     level is taken, and a sixteen-byte answer built at &7B80.  For each
;;     entry of the ROM's PALTAB in turn, PALETTE_INTENSITY works out how
;;     bright the colour is and ASSIGN_GREY_LEVEL claims a level for it.
;;     
;;     &7B80 is not scratch space in the file.  It is the thirty-six bytes
;;     installed in the system page at &4BA0 -- the stubs PRTOKV and
;;     others point at.  Once they are installed the copy here is dead, and
;;     DUMP takes it over: sixteen bytes of map over the block and
;;     twenty-five of level flags reaching five bytes past its end.
;; --------------------------------------------------------------------

; ---- BUILD_GREY_MAP ---- from &6881
BUILD_GREY_MAP:
               LD HL,PRTOKV_STUB               ; 6A69 21 90 7B
               LD B,&19                        ; 6A6C 06 19

;; --------------------------------------------------------------------
;; BUILD_GREY_MAP_LOOP -- &6A6E to &6A78
;;
;; Takes:     B, HL
;; Leaves:    B, DE, HL
;; --------------------------------------------------------------------

; ---- BUILD_GREY_MAP_LOOP ---- from &6A71 when B is not 0 yet
BUILD_GREY_MAP_LOOP:
               LD (HL),&00                     ; 6A6E 36 00
               INC HL                          ; 6A70 23
               DJNZ BUILD_GREY_MAP_LOOP        ; 6A71 10 FB
               LD HL,PALTAB                    ; 6A73 21 D8 55
               LD DE,INSTALL_ROM_PATCHES_2     ; 6A76 11 80 7B

;; --------------------------------------------------------------------
;; BUILD_GREY_MAP_LOOP2 -- &6A79 to &6A8B
;;
;; Takes:     DE, HL
;; Leaves:    A, F, BC, DE, HL
;; Ends:      RET
;;
;; ? calls RDA, ASSIGN_GREY_LEVEL.
;; --------------------------------------------------------------------

; ---- BUILD_GREY_MAP_LOOP2 ---- from &6A89 when A <> &E8
BUILD_GREY_MAP_LOOP2:
               PUSH DE                         ; 6A79 D5
               PUSH HL                         ; 6A7A E5
               CALL RDA                        ; 6A7B CD D1 45
               CALL ASSIGN_GREY_LEVEL          ; 6A7E CD 8C 6A
               POP HL                          ; 6A81 E1
               POP DE                          ; 6A82 D1
               LD (DE),A                       ; 6A83 12
               INC DE                          ; 6A84 13
               INC HL                          ; 6A85 23
               LD A,L                          ; 6A86 7D
               CP &E8                          ; 6A87 FE E8
               JR NZ,BUILD_GREY_MAP_LOOP2      ; 6A89 20 EE
               RET                             ; 6A8B C9

;; --------------------------------------------------------------------
;; ASSIGN_GREY_LEVEL -- &6A8C to &6A94
;;
;; Takes:     A
;; Leaves:    A, F, BC, D
;;
;; ? calls PALETTE_INTENSITY; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     Halve the intensity to get a level 0 to 24, then take that level or
;;     the nearest free one.
;; --------------------------------------------------------------------

; ---- ASSIGN_GREY_LEVEL ---- from &6A7E
ASSIGN_GREY_LEVEL:
               CALL PALETTE_INTENSITY          ; 6A8C CD C3 6A
               SRL A                           ; 6A8F CB 3F
               LD C,A                          ; 6A91 4F
               LD B,&00                        ; 6A92 06 00
               LD D,B                          ; 6A94 50

;; --------------------------------------------------------------------
;; FIND_FREE_GREY_LEVEL -- &6A95 to &6AA7
;;
;; Takes:     BC, D
;; Leaves:    A, F, D, HL
;; Preserves: BC (saved and restored)
;; Ends:      RET
;;
;; ? calls GREY_LEVEL_ABOVE.
;;
;; Shown for this routine in disasm/:
;;
;;     Look for an unclaimed level, trying the wanted one first and then
;;     up to three either side.
;;     
;;     GREY_LEVEL_ABOVE and GREY_LEVEL_BELOW are the two probes; each
;;     returns carry set with the level in A if it was free.  If nothing
;;     within three is free the wanted level is claimed anyway, which can
;;     give two colours the same grey.
;; --------------------------------------------------------------------

; ---- FIND_FREE_GREY_LEVEL ---- from &6AA3
FIND_FREE_GREY_LEVEL:
               LD HL,PRTOKV_STUB               ; 6A95 21 90 7B
               LD A,D                          ; 6A98 7A
               CP &03                          ; 6A99 FE 03
               LD A,C                          ; 6A9B 79
               RET NC                          ; 6A9C D0
               PUSH BC                         ; 6A9D C5
               CALL GREY_LEVEL_ABOVE           ; 6A9E CD A8 6A
               POP BC                          ; 6AA1 C1
               INC D                           ; 6AA2 14
               JR NC,FIND_FREE_GREY_LEVEL      ; 6AA3 30 F0
               LD (HL),&01                     ; 6AA5 36 01
               RET                             ; 6AA7 C9

;; --------------------------------------------------------------------
;; GREY_LEVEL_ABOVE -- &6AA8 to &6AB3
;;
;; Takes:     A, B, D, HL
;; Leaves:    A, F, C, HL
;; --------------------------------------------------------------------

; ---- GREY_LEVEL_ABOVE ---- from &6A9E
GREY_LEVEL_ABOVE:
               ADD A,D                         ; 6AA8 82
               CP &19                          ; 6AA9 FE 19
               JR NC,GREY_LEVEL_BELOW          ; 6AAB 30 07
               LD C,A                          ; 6AAD 4F
               ADD HL,BC                       ; 6AAE 09
               LD A,(HL)                       ; 6AAF 7E
               AND A                           ; 6AB0 A7
               SCF                             ; 6AB1 37
               LD A,C                          ; 6AB2 79
               RET Z                           ; 6AB3 C8

;; --------------------------------------------------------------------
;; GREY_LEVEL_BELOW -- &6AB4 to &6AC2
;;
;; Takes:     A, B, D
;; Leaves:    A, F, C, HL
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- GREY_LEVEL_BELOW ---- from &6AAB when A >= &19
GREY_LEVEL_BELOW:
               SUB D                           ; 6AB4 92
               SUB D                           ; 6AB5 92
               CCF                             ; 6AB6 3F
               RET NC                          ; 6AB7 D0
               LD C,A                          ; 6AB8 4F
               LD HL,PRTOKV_STUB               ; 6AB9 21 90 7B
               ADD HL,BC                       ; 6ABC 09
               LD A,(HL)                       ; 6ABD 7E
               AND A                           ; 6ABE A7
               LD A,C                          ; 6ABF 79
               RET NZ                          ; 6AC0 C0
               SCF                             ; 6AC1 37
               RET                             ; 6AC2 C9

;; --------------------------------------------------------------------
;; PALETTE_INTENSITY -- &6AC3 to &6AD3
;;
;; Takes:     A
;; Leaves:    A, F, BC
;; Ends:      RET
;;
;; Shown for this routine in disasm/:
;;
;;     How bright a SAM palette byte is, 0 to 49.
;;     
;;     The three high colour bits are worth four each and the three low
;;     ones two, which is the AND &70 shifted down twice and the AND &07
;;     doubled, and bit 3 -- bright -- adds seven on top.
;; --------------------------------------------------------------------

; ---- PALETTE_INTENSITY ---- from &6A8C
PALETTE_INTENSITY:
               LD C,A                          ; 6AC3 4F
               AND &07                         ; 6AC4 E6 07
               ADD A,A                         ; 6AC6 87
               LD B,A                          ; 6AC7 47
               LD A,C                          ; 6AC8 79
               AND &70                         ; 6AC9 E6 70
               RRCA                            ; 6ACB 0F
               RRCA                            ; 6ACC 0F
               ADD A,B                         ; 6ACD 80
               BIT 3,C                         ; 6ACE CB 59
               RET Z                           ; 6AD0 C8
               ADD A,&07                       ; 6AD1 C6 07
               RET                             ; 6AD3 C9

;; --------------------------------------------------------------------
;; CMD_DUMP_5 -- &6AD4 to &6AD5
;;
;; Takes:     nothing in registers
;; Leaves:    F
;;
;; Shown for this routine in disasm/:
;;
;;     DUMP 5, the text dump.  Sets carry and falls into the installer
;;     below, which is what picks the &4F00 entry rather than the &4F49
;;     one.  The manual: "the computer reads any characters it can
;;     recognize from the current screen window and sends them as single
;;     bytes".
;; --------------------------------------------------------------------

; ---- CMD_DUMP_5 ---- from &6829 when A = &05
CMD_DUMP_5:
               SCF                             ; 6AD4 37
               DEFB &3E                                                         ; 6AD5 >

;; --------------------------------------------------------------------
;; CMD_DUMP_4 -- &6AD6 to &6AF2
;;
;; Takes:     A
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? reaches the ROM through INP2; drives IN A,(HMPR), OUT (HMPR),A; calls CMR; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     DUMP 4, the unshaded graphic dump, and the common installer for both.
;;     Carry is clear on this path.  HMPR is zeroed, &0136 bytes are copied
;;     from DUMP_TEXT to &8F00 -- the ROM's INSTBUF at &4F00 -- and the copy
;;     is called through CMR at &4F00 for DUMP 5 or &4F49 for DUMP 4.  The
;;     inline parameters of those two calls read DKP2 and INP2, which are
;;     the ROM's own names for what it assembles at those addresses; here
;;     they are the block that has just been copied over them.
;; --------------------------------------------------------------------

; ---- CMD_DUMP_4 ---- from &682E when A = &04
CMD_DUMP_4:
               AND A                           ; 6AD6 A7
               IN A,(HMPR)                     ; 6AD7 DB FB
               PUSH AF                         ; 6AD9 F5
               XOR A                           ; 6ADA AF
               OUT (HMPR),A                    ; 6ADB D3 FB
               LD HL,DUMP_TEXT                 ; 6ADD 21 F9 6A
               LD DE,&8F00                     ; 6AE0 11 00 8F
               LD BC,&0136                     ; 6AE3 01 36 01
               LDIR                            ; 6AE6 ED B0
               POP AF                          ; 6AE8 F1
               OUT (HMPR),A                    ; 6AE9 D3 FB
               JR C,CMD_DUMP_4_DONE            ; 6AEB 38 06
               ; call the ROM at INP2 with ROM1 paged in, and page back on the way out
               CALL CMR                        ; 6AED CD F0 44
               DEFW INP2                      ; 6AF0 49 4F
               RET                             ; 6AF2 C9

;; --------------------------------------------------------------------
;; CMD_DUMP_4_DONE -- &6AF3 to &6AF8
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? reaches the ROM through DKP2; calls CMR; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- CMD_DUMP_4_DONE ---- from &6AEB
CMD_DUMP_4_DONE:
               ; call the ROM at DKP2 with ROM1 paged in, and page back on the way out
               CALL CMR                        ; 6AF3 CD F0 44
               DEFW DKP2                      ; 6AF6 00 4F
               RET                             ; 6AF8 C9

;; --------------------------------------------------------------------
;; DUMP_TEXT -- &6AF9 to &6B13
;;
;; Takes:     nothing in registers
;; Leaves:    A, BC, DE, HL
;;
;; Shown for this routine in disasm/:
;;
;;     DUMP 5's half of the block, at &4F00 once moved.  It saves PRRHS,
;;     sets it to &FF so nothing wraps, selects stream 3, and reads UWRHS,
;;     UWLHS, UWTOP and UWBOT -- the four bytes bounding the upper screen
;;     window -- into C, E, D and B.  The loop then calls the ROM's JNCHAR
;;     at &0184 for each position, which is SCREEN$: the manual says "the
;;     ROM's SCREEN$ routine is used ... an uncoloured version is compared
;;     with the character set in an attempt to match the character", and a
;;     failure prints a space.  DEVICE is zeroed around each call and put
;;     back.
;; --------------------------------------------------------------------

; ---- DUMP_TEXT ---- from &6ADD
DUMP_TEXT:
               LD A,(PRRHS)                    ; 6AF9 3A 0E 5A  from here to &6C2E this code is written for &4F00: subtract &1BF9 from any address in it
               PUSH AF                         ; 6AFC F5
               LD A,&FF                        ; 6AFD 3E FF
               ; self-modifying: patches the operand of the LD at &5A0B
               LD (PRRHS),A                    ; 6AFF 32 0E 5A
               LD A,&03                        ; 6B02 3E 03
               CALL STREAM                     ; 6B04 CD 12 01
               LD A,&0D                        ; 6B07 3E 0D
               RST PRINT_A                     ; 6B09 D7
               LD HL,UWRHS                     ; 6B0A 21 38 5A
               LD C,(HL)                       ; 6B0D 4E
               INC HL                          ; 6B0E 23
               LD E,(HL)                       ; 6B0F 5E
               INC HL                          ; 6B10 23
               LD D,(HL)                       ; 6B11 56
               INC HL                          ; 6B12 23
               LD B,(HL)                       ; 6B13 46

;; --------------------------------------------------------------------
;; DUMP_TEXT_LOOP -- &6B14 to &6B25
;;
;; Takes:     BC, DE
;; Leaves:    A, HL
;; --------------------------------------------------------------------

; ---- DUMP_TEXT_LOOP ---- from &6B2F when A <> C, &6B3B when A <> B
DUMP_TEXT_LOOP:
               PUSH BC                         ; 6B14 C5
               PUSH DE                         ; 6B15 D5
               LD HL,DEVICE                    ; 6B16 21 73 5A
               LD A,(HL)                       ; 6B19 7E
               LD (HL),&00                     ; 6B1A 36 00
               PUSH AF                         ; 6B1C F5
               PUSH HL                         ; 6B1D E5
               CALL JNCHAR                     ; 6B1E CD 84 01
               LD A,&20                        ; 6B21 3E 20
               JR C,DUMP_TEXT_1                ; 6B23 38 01
               LD A,(HL)                       ; 6B25 7E

;; --------------------------------------------------------------------
;; DUMP_TEXT_1 -- &6B26 to &6B41
;;
;; Takes:     nothing in registers
;; Leaves:    A, F, BC, DE, HL
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- DUMP_TEXT_1 ---- from &6B23
DUMP_TEXT_1:
               POP HL                          ; 6B26 E1
               POP BC                          ; 6B27 C1
               LD (HL),B                       ; 6B28 70
               RST PRINT_A                     ; 6B29 D7
               POP DE                          ; 6B2A D1
               POP BC                          ; 6B2B C1
               LD A,E                          ; 6B2C 7B
               INC E                           ; 6B2D 1C
               CP C                            ; 6B2E B9
               JR NZ,DUMP_TEXT_LOOP            ; 6B2F 20 E3
               LD A,&0D                        ; 6B31 3E 0D
               RST PRINT_A                     ; 6B33 D7
               LD A,(UWLHS)                    ; 6B34 3A 39 5A
               LD E,A                          ; 6B37 5F
               LD A,D                          ; 6B38 7A
               INC D                           ; 6B39 14
               CP B                            ; 6B3A B8
               JR NZ,DUMP_TEXT_LOOP            ; 6B3B 20 D7
               POP AF                          ; 6B3D F1
               ; self-modifying: patches the operand of the LD at &5A0B
               LD (PRRHS),A                    ; 6B3E 32 0E 5A
               RET                             ; 6B41 C9

;; --------------------------------------------------------------------
;; DUMP_UNSHADED -- &6B42 to &6B59
;;
;; Takes:     nothing in registers
;; Leaves:    A, F, DE, HL
;;
;; Shown for this routine in disasm/:
;;
;;     DUMP 4's half, at &4F49 once moved.  Selects stream &FB and works
;;     through the ROM's dump control strings -- &5A16 and &5A1F are GCM1
;;     and GCM2, whose first byte is the number of characters to send --
;;     switching on MODE at &5A40 and on the settings at &5A12 and &5A15.
;;     The manual calls it "an unshaded dump in which anything which is the
;;     current PAPER colour comes out white, and anything else comes out
;;     black", and points at the User's Guide for the SVARs that size it.
;; --------------------------------------------------------------------

DUMP_UNSHADED:
               LD A,&FB                        ; 6B42 3E FB
               CALL STREAM                     ; 6B44 CD 12 01
               LD DE,&5A16                     ; 6B47 11 16 5A
               CALL &500B                      ; 6B4A CD 0B 50  &500B once this block is moved, not the label shown
               LD HL,(&5A2D)                   ; 6B4D 2A 2D 5A
               LD A,(&5A15)                    ; 6B50 3A 15 5A
               DEC A                           ; 6B53 3D
               LD A,(&5A12)                    ; 6B54 3A 12 5A
               JR Z,DUMP_UNSHADED_1            ; 6B57 28 01
               ADD A,A                         ; 6B59 87

;; --------------------------------------------------------------------
;; DUMP_UNSHADED_1 -- &6B5A to &6B6C
;;
;; Takes:     A, HL
;; Leaves:    A, F, C, DE
;; --------------------------------------------------------------------

; ---- DUMP_UNSHADED_1 ---- from &6B57 when A reaches 0
DUMP_UNSHADED_1:
               LD C,A                          ; 6B5A 4F
               PUSH HL                         ; 6B5B E5
               LD DE,&5A1F                     ; 6B5C 11 1F 5A
               CALL &500B                      ; 6B5F CD 0B 50  &500B once this block is moved, not the label shown
               LD A,(MODE)                     ; 6B62 3A 40 5A
               CP &02                          ; 6B65 FE 02
               LD A,(&5A13)                    ; 6B67 3A 13 5A
               JR NZ,DUMP_UNSHADED_2           ; 6B6A 20 01
               ADD A,A                         ; 6B6C 87

;; --------------------------------------------------------------------
;; DUMP_UNSHADED_2 -- &6B6D to &6B74
;;
;; Takes:     A
;; Leaves:    A, F, B, D
;; --------------------------------------------------------------------

; ---- DUMP_UNSHADED_2 ---- from &6B6A when A <> &02
DUMP_UNSHADED_2:
               LD B,A                          ; 6B6D 47
