               EX (SP),HL                      ; 7430 E3
               EX DE,HL                        ; 7431 EB
               RST NEXT_CHAR                   ; 7432 E7
               PUSH AF                         ; 7433 F5
               EX DE,HL                        ; 7434 EB
               IN A,(HMPR)                     ; 7435 DB FB
               ; to the alternate register set and back again
               EX AF,AF'                       ; 7437 08
               LD A,(FISCRNP)                  ; 7438 3A 9F 5C
               AND PAGEMASK                    ; 743B E6 1F
               OUT (HMPR),A                    ; 743D D3 FB
               POP AF                          ; 743F F1
