               OUT (C),A                       ; 7715 ED 79
               LD A,&04                        ; 7717 3E 04
               OUT (C),A                       ; 7719 ED 79
               LD HL,&7FE6                     ; 771B 21 E6 7F
               LD (DOSSTK),HL                  ; 771E 22 59 5C
               LD HL,SYS_EDITV_EDITOR          ; 7721 21 66 48  &4866 likewise, inside the second stub
