               LD HL,&3A31                     ; 7733 21 31 3A
               LD (DOS_PTH1),HL                ; 7736 22 13 BF
               INC L                           ; 7739 2C
               LD (DOS_PTH2),HL                ; 773A 22 39 BF
               LD HL,&45A1                     ; 773D 21 A1 45
               LD (BSTKEND),HL                 ; 7740 22 C4 5B
