;; --------------------------------------------------------------------
;; DISPATCH_ON_COMMAND_TOKEN_4 -- &7CBA to &7CCF
;;
;; Takes:     nothing in registers
;; Leaves:    HL
;; --------------------------------------------------------------------

; ---- DISPATCH_ON_COMMAND_TOKEN_4 ---- from &7C84 when A = &B3, &7C88 when A = &B0
DISPATCH_ON_COMMAND_TOKEN_4:
               POP HL                          ; 7CBA E1
               RST ERR_HOOK                    ; 7CBB CF
               DEFB &AE                       ; 7CBC AE hook code, handled by HK_RCPTCH
               BIT 0,C                         ; 7CBD CB 41
               JP NZ,ANYI                      ; 7CBF C2 49 00
               LD A,(&5C5C)                    ; 7CC2 3A 5C 5C
               LD HL,FISCRNP                   ; 7CC5 21 9F 5C
               ADD A,L                         ; 7CC8 85
               LD L,A                          ; 7CC9 6F
               LD L,(HL)                       ; 7CCA 6E
               LD A,(LINICOLS)                 ; 7CCB 3A 00 56
               LD H,A                          ; 7CCE 67
               XOR A                           ; 7CCF AF

;; --------------------------------------------------------------------
;; CALLBACK_HCMDV_LOOP -- &7CD0 to &7CDC
;;
;; Takes:     A, B, HL
;; Leaves:    A, F
;; Ends:      JP
