               LD A,(LINICOLS)                 ; 7CDD 3A 00 56
               INC A                           ; 7CE0 3C
               JR Z,CALLBACK_HCMDV_1           ; 7CE1 28 0E
               LD A,(&5C5B)                    ; 7CE3 3A 5B 5C
               AND A                           ; 7CE6 A7
               JR Z,CALLBACK_HCMDV_1           ; 7CE7 28 08
               LD HL,FISCRNP                   ; 7CE9 21 9F 5C
               ADD A,L                         ; 7CEC 85
