;; --------------------------------------------------------------------
               OUT (HMPR),A                    ; 7E4C D3 FB
               LD A,C                          ; 7E4E 79
               ; to the alternate register set and back again
               EXX                             ; 7E4F D9
               RET                             ; 7E50 C9

