;; ------------------------------------------------------------------
;; Tokenised SAM BASIC.  The end of the page holds fragments of BASIC
;; source that MasterBASIC pastes into a program -- the profiler report
;; ("TOTAL FRAMES", "MEMORY USED") and its key prompts among them.
;;
;; Each fragment is a run of program lines: two bytes of line number,
;; high byte first -- the one word in either listing that is not
;; little-endian, so it stays two DEFBs where a DEFW would reverse
;; it -- then two bytes of length low first, which is a DEFW, then
;; the statement, then &0D.  The
;; run starts and ends part way through a line.  Keywords are named
;; from the SAM ROM's own token tables (see tools/sambasic.py); a
;; number is its digits followed by &0E and five bytes of value; and
;; inside a string &80-&A8 are graphics characters, not keywords.
;; ------------------------------------------------------------------

MBTEXT:
;
; STEP (lngt)
               DEFB T_STEP                    ; 7E6B STEP
               DEFM "(lngt)"
               DEFB TK_CR                     ; 7E72 end of line
;
; 11400 PRINT "   TOTAL FRAMES: ";CODE g$(frms)
               DEFB &2C,&88                   ; 7E73 line 11400, high byte first
               DEFW 32                        ; length, low byte first
               DEFB T_PRINT                   ; 7E77 PRINT
               DEFM """   TOTAL FRAMES: "";"
               DEFB FN_PFX,F_CODE             ; 7E8C CODE
               DEFM "g$(frms)"
               DEFB TK_CR                     ; 7E96 end of line
;
; 11410 PRINT "    MEMORY USED: ";CODE g$(frms)*(CODE g$(fslo)+CODE g$(fshi)*256)*(1+((CODE g$(flg2) BAND 32)=32))
               DEFB &2C,&92                   ; 7E97 line 11410, high byte first
               DEFW 111                       ; length, low byte first
               DEFB T_PRINT                   ; 7E9B PRINT
               DEFM """    MEMORY USED: "";"
               DEFB FN_PFX,F_CODE             ; 7EB0 CODE
               DEFM "g$(frms)*("
               DEFB FN_PFX,F_CODE             ; 7EBC CODE
               DEFM "g$(fslo)+"
               DEFB FN_PFX,F_CODE             ; 7EC7 CODE
               DEFM "g$(fshi)*256"
               DEFB TK_NUM,&00,&00,&00,&01,&00 ; 7ED5 = 256
               DEFM ")*(1"
               DEFB TK_NUM,&00,&00,&01,&00,&00 ; 7EDF = 1
               DEFM "+(("
               DEFB FN_PFX,F_CODE             ; 7EE8 CODE
               DEFM "g$(flg2) "
               DEFB FN_PFX,F_BAND             ; 7EF3 BAND
               DEFM "32"
               DEFB TK_NUM,&00,&00,&20,&00,&00 ; 7EF7 = 32
               DEFM ")=32"
               DEFB TK_NUM,&00,&00,&20,&00,&00 ; 7F01 = 32
               DEFM "))"
